@startuml

class InsuranceCompany {}

class Customer {
  + name : string
  + address : string
  + customerId : int
}

class Broker {
  + brokerId : int
  + name : string
}

class Policy {
  + policyType : string
  + coverageDetails : string
}

class Offer {
  + offerId : int
  + validityDate : date
  + status : string
}

class Contract {
  + contractId : int
  + signingDate : date
  + billingFrequency : string
  + price : float
}

class ClaimCase {
  + caseId : int
  + description : string
  + status : string
}

class Estimator {
  + estimatorId : int
  + areaOfExpertise : string
}

class EstimatorReport {
  + reportId : int
  + findings : string
  + dateIssued : date
}

class CompensationDecision {
  + decisionId : int
  + approvedAmount : float
  + eligibleCosts : string
}

class Payment {
  + paymentId : int
  + amount : float
  + paymentDate : date
}

InsuranceCompany "1" -- "*" Customer
Broker "1" -- "*" Customer : manages
Customer "1" -- "*" Contract
Contract "1" -- "1" Policy
Offer "0..1" -- "1" Customer
Offer "1" -- "0..1" Contract
Customer "1" -- "*" ClaimCase
ClaimCase "1" *-- "1..*" EstimatorReport
Estimator "1" -- "*" EstimatorReport : assesses
ClaimCase "1" -- "0..1" CompensationDecision
CompensationDecision "1" -- "1" Payment
Payment "1" -- "1" Customer

@enduml

